cd "C:\Users\olive_\OneDrive\Documentos\codigo\Momma\momma-stock-insight" && node -e "
const https = require('https');

const ACCESS_TOKEN = 'sbp_7efde3fa700189a9a3f708f8f591234e4cea1f71';
const PROJECT_ID = 'jaumyfyeueayibbxunxc';

const verifySQL = \`
-- Views
SELECT 'VIEW' as object_type, table_name as name
FROM information_schema.views
WHERE table_schema = 'public' AND table_name = 'vw_user_behavioral_profile'

UNION ALL

-- Functions/RPCs
SELECT 'FUNCTION', routine_name
FROM information_schema.routines
WHERE routine_schema = 'public'
  AND routine_name IN ('fn_update_behavioral_profile', 'get_behavioral_profile', 'get_distilled_patterns')

UNION ALL

-- Trigger
SELECT 'TRIGGER', trigger_name
FROM information_schema.triggers
WHERE trigger_schema = 'public' AND trigger_name = 'trg_gidape_events_update_profile'

UNION ALL

-- New columns on mia_user_patterns
SELECT 'COLUMN_mia_user_patterns', column_name
FROM information_schema.columns
WHERE table_schema = 'public'
  AND table_name = 'mia_user_patterns'
  AND column_name IN ('top_pages','top_flows','peak_hours','avg_dwell_ms','feature_usage_map','loop_count','last_loop_detected_at','mia_suggestion_act_rate','counterfactual_avg_dwell_ms','behavioral_updated_at')

ORDER BY 1, 2;
\`;

const body = JSON.stringify({ query: verifySQL });

const options = {
  hostname: 'api.supabase.com',
  path: '/v1/projects/' + PROJECT_ID + '/database/query',
  method: 'POST',
  headers: {
    'Authorization': 'Bearer ' + ACCESS_TOKEN,
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(body)
  }
};

const req = https.request(options, (res) => {
  let data = '';
  res.on('data', chunk => data += chunk);
  res.on('end', () => {
    console.log('Status:', res.statusCode);
    const result = JSON.parse(data);
    if (Array.isArray(result)) {
      result.forEach(r => console.log(r.object_type + ': ' + r.name));
    } else {
      console.log(JSON.stringify(result, null, 2));
    }
  });
});

req.on('error', e => console.error('Error:', e.message));
req.write(body);
req.end();
" 2>&1
